<?php

namespace App\Http\Requests;

class StoreGenerationRequest extends EstimateGenerationRequest
{
    /** @return array<string, mixed> */
    public function rules(): array
    {
        return [
            // Generated by the browser once per form. It becomes the row's id and the
            // Pixelforge Idempotency-Key, so a double click cannot create two generations.
            'uuid' => ['required', 'uuid'],
            ...parent::rules(),
        ];
    }
}
